+/**
+ * hdd_init_injection_session_id() - Initialize session ID counter
+ */
+static void hdd_init_injection_session_id(void)
+{
+	qdf_atomic_init(&g_injection_session_id);
+	qdf_atomic_set(&g_injection_session_id, 1);
+}
