+	&hdd_injection_max_frame_size_attr.attr,
+	&hdd_injection_max_queue_size_attr.attr,
+	&hdd_injection_rate_window_ms_attr.attr,
+	&hdd_injection_require_monitor_mode_attr.attr,
+	NULL,
+};
