+ * This function checks the global enable flag that can be controlled
+ * via sysfs interface.
+ *
+ * Return: true if globally enabled, false otherwise
+ */
+bool hdd_injection_is_globally_enabled(void)
+{
+	return g_injection_global_enable;
+}
