+	/* Add subtype-specific fields */
+	switch (subtype) {
+	case 0x40: /* RTS */
+		if (frame_len >= 16) {
+			/* Transmitter address */
+			qdf_mem_copy(frame_data + 10, test_addr, QDF_MAC_ADDR_SIZE);
