+	case 0x90: /* BAR */
+		if (frame_len >= 20) {
+			/* Transmitter address */
+			qdf_mem_copy(frame_data + 10, test_addr, QDF_MAC_ADDR_SIZE);
+			/* BAR control */
+			*(uint16_t *)(frame_data + 16) = 0x1000; /* TID 1 */
+			/* BAR information */
+			*(uint16_t *)(frame_data + 18) = 0x1000;
+		}
+		break;
+	}
+
+	return QDF_STATUS_SUCCESS;
+}
